// @file ./experiments/letta-constrained.ts
import { defineExperiment } from "niceeval";
import { lettaAgent } from "../agents/letta.ts";

export default defineExperiment({
  description: "Letta memory-agent comparison with a constrained tool-step budget",
  agent: lettaAgent({
    baseUrl: process.env.LETTA_BASE_URL ?? "http://127.0.0.1:8283",
    agentId: process.env.LETTA_AGENT_ID ?? "",
    apiKey: process.env.LETTA_API_KEY,
    maxSteps: 3,
  }),
  attempts: 1,
});
// @file ./experiments/letta-standard.ts
import { defineExperiment } from "niceeval";
import { lettaAgent } from "../agents/letta.ts";

export default defineExperiment({
  description: "Letta memory-agent baseline with the normal tool-step budget",
  agent: lettaAgent({
    baseUrl: process.env.LETTA_BASE_URL ?? "http://127.0.0.1:8283",
    agentId: process.env.LETTA_AGENT_ID ?? "",
